"""Where things are. One place, so no path is spelled twice.

Every path is absolute and anchored on the repository root rather than the working
directory: a relative path inside a persisted view resolves at query time, so a view created
from here would break the moment a page opened the same warehouse from elsewhere.
"""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path


@dataclass(frozen=True, slots=True)
class Project:
    """The repository, as the layers see it."""

    root: Path

    @classmethod
    def discover(cls, start: Path | None = None) -> Project:
        here = (start or Path.cwd()).absolute()
        for candidate in (here, *here.parents):
            if (candidate / "pyproject.toml").is_file():
                return cls(root=candidate)
        raise FileNotFoundError(f"no project root above {here}")

    @property
    def contracts(self) -> Path:
        return self.root / "das" / "contracts"

    @property
    def fixtures(self) -> Path:
        return self.root / "das" / "fixtures"

    @property
    def lake(self) -> Path:
        return self.root / "das" / "lake"

    @property
    def das_sql(self) -> Path:
        return self.root / "das" / "sql"

    @property
    def pipelines(self) -> Path:
        return self.root / ".dlt"

    @property
    def warehouse(self) -> Path:
        return self.root / "warehouse.duckdb"

    @property
    def dab(self) -> Path:
        return self.root / "dab"

    @property
    def mappings(self) -> Path:
        return self.dab / "mappings"

    @property
    def sqlfluff_config(self) -> Path:
        return self.root / ".sqlfluff"

    @property
    def model(self) -> Path:
        return self.dab / "model.yaml"

    @property
    def uss(self) -> Path:
        return self.dab / "uss.yaml"

    @property
    def dar_sql(self) -> Path:
        return self.root / "dar" / "uss"

    @property
    def destination(self) -> Path:
        return self.root / "destinations" / "app.py"

    @property
    def screenshots(self) -> Path:
        return self.root / ".screenshots"

    @property
    def browser_cache(self) -> Path:
        return self.root / ".browsers"

    @property
    def engine_binary(self) -> Path:
        return self.root / "bin" / "linux-amd64" / "daana-cli"

    def contract_paths(self) -> tuple[Path, ...]:
        return tuple(sorted(self.contracts.glob("*.yaml")))

=== question.py ===
"""A business question: the specification, the acceptance test and what a page renders.

It is a data file rather than code, which is what keeps the vocabulary of one business out
of the machinery that runs it. The runner discovers questions and asserts over them; it
names nothing. ADR 0005.
"""

from __future__ import annotations

import re
from dataclasses import dataclass
from enum import StrEnum
from pathlib import Path

import yaml

FRONT_MATTER = re.compile(r"\A---\n(.*?)\n---\n(.*)\Z", re.DOTALL)
TOKEN = re.compile(r"\{\{([^}]+)\}\}")

STAGED = "staged.sql"
USS = "uss.sql"


class QuestionError(Exception):
    """A question that cannot be answered as written."""


class Status(StrEnum):
    DRAFT = "draft"
    RED = "red"
    GREEN = "green"
    SUPERSEDED = "superseded"


@dataclass(frozen=True, slots=True)
class Question:
    directory: Path
    id: str
    status: Status
    persona: str
    question: str
    dimensions: tuple[str, ...]
    defines: tuple[str, ...]
    staged_sql: str
    uss_sql: str
    body: str

    @property
    def tokens(self) -> tuple[str, ...]:
        return tuple(str(match).strip() for match in TOKEN.findall(self.body))


def without_comments(sql: str) -> str:
    """The SQL, without its commentary. A comment explaining a rule does not break it."""
    return "\n".join(line for line in sql.splitlines() if not line.lstrip().startswith("--"))


def read_question(directory: Path) -> Question:
    text = (directory / "question.md").read_text()
    parsed = FRONT_MATTER.match(text)
    if parsed is None:
        raise QuestionError(f"{directory}: question.md has no front matter")
    front = yaml.safe_load(parsed.group(1))
    return Question(
        directory=directory,
        id=str(front["id"]),
        status=Status(str(front["status"])),
        persona=str(front["persona"]),
        question=str(front["question"]),
        dimensions=tuple(str(d) for d in front["dimensions"]),
        defines=tuple(str(d) for d in front["defines"]),
        staged_sql=(directory / STAGED).read_text(),
        uss_sql=(directory / USS).read_text(),
        body=parsed.group(2),
    )


def read_questions(root: Path) -> tuple[Question, ...]:
    return tuple(
        read_question(directory)
        for directory in sorted(root.iterdir())
        if (directory / "question.md").is_file()
    )


def check_question(question: Question, defined: dict[str, str]) -> None:
    """Refuse a question that cannot be answered, or answered honestly."""
    for token in question.tokens:
        if token not in defined:
            raise QuestionError(
                f"{question.id}: {{{{{token}}}}} resolves to nothing. A question references "
                f"definitions and never restates one, so a token with no definition behind "
                f"it is a gap in the model -- fill it there first."
            )
    missing = [name for name in question.defines if name not in defined]
    if missing:
        raise QuestionError(f"{question.id}: declares {missing}, which nothing defines")

    lowered = without_comments(question.staged_sql).lower()
    for forbidden in ("dab.", "dab__", "dar__uss"):
        if forbidden in lowered:
            raise QuestionError(
                f"{question.id}: the control query mentions {forbidden!r}. It must compute "
                f"the answer independently, or agreement between the two proves nothing."
            )
    if "dar__uss" not in without_comments(question.uss_sql).lower():
        raise QuestionError(f"{question.id}: the answer query does not read the star schema")

"""A structural reading of the business model. It carries meaning; it never reads it.

The definitions in the model are the only explanation of the data there is. This module
moves them around -- into a glossary, into a check that a question's references resolve --
and never composes one, because a composed definition is a second explanation that nobody
wrote and nobody reviews.
"""

from __future__ import annotations

from dataclasses import dataclass
from enum import StrEnum
from pathlib import Path

import yaml


class AttributeType(StrEnum):
    """The modelling language's whole type vocabulary. Semantic, not physical."""

    STRING = "STRING"
    NUMBER = "NUMBER"
    UNIT = "UNIT"
    START_TIMESTAMP = "START_TIMESTAMP"
    END_TIMESTAMP = "END_TIMESTAMP"


@dataclass(frozen=True, slots=True)
class Attribute:
    id: str
    type: AttributeType
    definition: str

    @property
    def column(self) -> str:
        """How this attribute is spelled in the generated layer."""
        return self.id.lower()

    @property
    def is_number(self) -> bool:
        return self.type is AttributeType.NUMBER

    @property
    def is_date(self) -> bool:
        return self.type in (AttributeType.START_TIMESTAMP, AttributeType.END_TIMESTAMP)


@dataclass(frozen=True, slots=True)
class Entity:
    id: str
    definition: str
    attributes: tuple[Attribute, ...]

    @property
    def object_name(self) -> str:
        """The generated layer's name for this entity: snake_case, singular."""
        return self.id.lower()

    @property
    def key_column(self) -> str:
        return f"{self.object_name}_key"

    @property
    def source_key(self) -> str:
        """What the modelling engine calls this entity's key, in its own casing."""
        return f"{self.id}_key"

    def attribute(self, attribute_id: str) -> Attribute:
        for attribute in self.attributes:
            if attribute.id == attribute_id:
                return attribute
        raise KeyError(f"{self.id} has no attribute {attribute_id!r}")


@dataclass(frozen=True, slots=True)
class Model:
    path: Path
    entities: tuple[Entity, ...]

    def entity(self, entity_id: str) -> Entity:
        for entity in self.entities:
            if entity.id == entity_id:
                return entity
        raise KeyError(f"{self.path} has no entity {entity_id!r}")

    def definitions(self) -> dict[str, str]:
        """Every definition, by the token that refers to it. Copied, never composed."""
        found: dict[str, str] = {}
        for entity in self.entities:
            found[entity.id] = entity.definition
            for attribute in entity.attributes:
                found[f"{entity.id}.{attribute.id}"] = attribute.definition
        return found


def read_model(path: Path) -> Model:
    document = yaml.safe_load(path.read_text())["model"]
    entities = tuple(
        Entity(
            id=str(entity["id"]),
            definition=str(entity["definition"]),
            attributes=tuple(
                Attribute(
                    id=str(attribute["id"]),
                    type=AttributeType(str(attribute["type"])),
                    definition=str(attribute["definition"]),
                )
                for attribute in entity["attributes"]
            ),
        )
        for entity in document["entities"]
    )
    return Model(path=path, entities=entities)
